import React from "react";
import InfiniteScroll from "react-infinite-scroll-component";
import SinglePost from "./singelPostComponent";

class Home extends React.Component {

    constructor(props) {
        super(props);

        this.state = {
            posts: [],
            loading: true,
            base_URL: "",
            nextPage: "http://localhost:8000/api/",   // first page
            hasMore: true
        };
    }

    componentDidMount() {
        this.loadMore();
    }

    loadMore = () => {
        if (!this.state.nextPage) {
            this.setState({ hasMore: false });
            return;
        }

        fetch(this.state.nextPage)
            .then(res => res.json())
            .then(json => {

                const newPosts = json.posts.data;

                this.setState(prev => ({
                    posts: [...prev.posts, ...newPosts],
                    base_URL: json.base_URL,
                    nextPage: json.posts.next_page_url, // Laravel pagination
                    hasMore: json.posts.next_page_url !== null
                }));
            })
            .catch(err => {
                console.log("ERR:", err);
                this.setState({ hasMore: false });
            });
    };

    render() {
        return (
            <main className="container mt-4 pt-5">

                <InfiniteScroll
                    dataLength={this.state.posts.length}
                    next={this.loadMore}
                    hasMore={this.state.hasMore}
                    loader={<p>در حال بارگذاری...</p>}
                    endMessage={<p className="text-center mt-4">تمام پست‌ها نمایش داده شد</p>}
                >
                    <div className="container-fluid mt-5">
                        {this.state.posts.map(post => (
                            <SinglePost
                                key={post.id}
                                id={post.id}
                                title={post.title}
                                text={post.text}
                                img={post.img}
                                base_URL={this.state.base_URL}
                                user_img={post.user_img}
                                name={post.name}
                                count_like={post.count_like}
                                count_comment={post.count_comment}
                                display_time={post.display_time}
                            />
                        ))}
                    </div>
                </InfiniteScroll>

            </main>
        );
    }
}

export default Home;
